import styled from '@emotion/styled';
import { theme } from 'theme';

export const StyledBodyContainer = styled.div({
  padding: '0 0 16px',
});

export const StyledWaterfallChartContainer = styled.div(() => ({
  width: '100%',
  height: '360px',
  padding: '0 8px 0',
  '& [data-testid="interactive-chart-wrapper"]': {
    overflow: 'visible',
  },
}));

export const StyledLegendContainer = styled.div({
  marginTop: 0,
  marginBottom: 0,
  borderTop: `1px solid ${theme.colors.charts.bg.diverging.Zero}`,
  paddingTop: '8px',
});

export const StyledComparisonLineContainer = styled.div({
  padding: '20px 16px 16px',
});
